import json,os,sys,urllib.request
B="http://localhost:8000/api/v1"
PAYLOAD=json.loads('{"source":"your-roster:survey:522b30ec-3c03-42a8-aaef-632b4cabf33d","scenarios":[{"key":"roster-522b30ec3c-236a5b99f2","title":"In a FAR Part 15 best value tradeoff, the contracting officer wants to add an evaluation factor after proposals have…","input":{"prompt":"In a FAR Part 15 best value tradeoff, the contracting officer wants to add an evaluation factor after proposals have come in. What has to happen, and why?"},"reference_answer":"You can\'t just add it. FAR 15.304(d) says the factors and significant subfactors, and how important each one is relative to the others, have to be in the solicitation, because that\'s what offerors write their proposals to. If the evaluation needs a new factor, you amend the solicitation under 15.206 and give every offeror in the competition a chance to revise. Evaluating against a factor nobody was told about is the classic protest ground, and a memo to the file doesn\'t fix it.","reference_sources":[{"kind":"expert_answers","count":1,"survey":"Procurement Judgment Check (Example)"}],"criteria":[{"id":"c1","text":"Says every factor and significant subfactor, and their relative importance, must be stated in the solicitation (FAR 15.304(d))."},{"id":"c2","text":"Says adding or changing a factor needs an amendment to the solicitation (FAR 15.206)."},{"id":"c3","text":"Says offerors must get a chance to revise their proposals after the amendment."},{"id":"c4","text":"Doesn\'t suggest that a note to the file is enough on its own."}],"tags":["your-roster","survey:522b30ec3c","split:private"],"required_expertise":["acquisition"]},{"key":"roster-522b30ec3c-f01064c7f7","title":"When does past performance have to be evaluated in a negotiated competitive acquisition, and how is an offeror with no…","input":{"prompt":"When does past performance have to be evaluated in a negotiated competitive acquisition, and how is an offeror with no record rated?"},"reference_answer":"Past performance has to be evaluated in negotiated competitive buys expected to go over the simplified acquisition threshold, 15.304(c)(3). The contracting officer can decide it isn\'t appropriate for a particular buy, but has to document why. An offeror without a relevant record gets a neutral rating: under 15.305(a)(2)(iv) they can\'t be rated favorably or unfavorably on past performance.","reference_sources":[{"kind":"expert_answers","count":1,"survey":"Procurement Judgment Check (Example)"}],"criteria":[{"id":"c1","text":"Says it must be evaluated when the buy is expected to exceed the simplified acquisition threshold (FAR 15.304(c)(3))."},{"id":"c2","text":"Says the contracting officer may decide it isn\'t appropriate, and must document why."},{"id":"c3","text":"Says an offeror with no relevant record can\'t be rated favorably or unfavorably (FAR 15.305(a)(2)(iv))."}],"tags":["your-roster","survey:522b30ec3c","split:private"],"required_expertise":["acquisition"]}],"evaluation":{"key":"survey-522b30ec3c","name":"Procurement Judgment Check (Example) (Your Roster survey)","tag":"survey:522b30ec3c"}}')
def call(m,p,body=None,tok=None):
    r=urllib.request.Request(B+p,method=m,data=json.dumps(body).encode() if body is not None else None,headers={"content-type":"application/json",**({"authorization":"Bearer "+tok} if tok else {})})
    try:
        with urllib.request.urlopen(r,timeout=30) as x: return x.status,json.loads(x.read() or b"null")
    except urllib.error.HTTPError as e: return e.code,e.read().decode()[:400]
s,t=call("POST","/auth/login",{"email":os.environ["AEGIS_BOOTSTRAP_EMAIL"],"password":os.environ["AEGIS_BOOTSTRAP_PASSWORD"]})
if s!=200: print("AEG login",s,t); sys.exit(1)
tok=t["access_token"]
orgs=call("GET","/organizations",tok=tok)[1]; progs=call("GET","/programs",tok=tok)[1]; projs=call("GET","/projects",tok=tok)[1]
print("AEG orgs",[(o["id"],o["name"]) for o in orgs]); print("AEG programs",[(p["id"],p["name"]) for p in progs]); print("AEG projects",[(p["id"],p["name"],p["slug"]) for p in projs])
if sys.argv[1:]!=["go"]: sys.exit(0)
proj=next((p for p in projs if p["slug"]=="procurement-judgment-example"),None)
if not proj:
    prog=next((p for p in progs if p["name"]=="Expert Benchmark Program (Example)"),None)
    if not prog:
        s,prog=call("POST","/programs",{"organization_id":next(o["id"] for o in orgs if o["name"]=="Program Executive Office (demonstration)"),"name":"Expert Benchmark Program (Example)","description":"Example data (fictional): questions written and answered by made-up experts, for the team to follow one expert from Your Roster through Light-Lux to Aegis Eval."},tok); print("AEG program",s)
    s,proj=call("POST","/projects",{"program_id":prog["id"],"name":"Procurement Judgment (Example)","slug":"procurement-judgment-example","description":"Example data (fictional). Survey questions from Light-Lux with a made-up expert's answers as the reference.","classification":"UNCLASSIFIED"},tok); print("AEG project",s,proj if s>=300 else "")
s,out=call("POST","/projects/%s/scenarios/import"%proj["id"],PAYLOAD,tok)
print("AEG import",s); print("AEGPROJ",proj["id"]); print("AEGOUT",json.dumps(out if isinstance(out,dict) else {"error":out}).replace("'","\\u0027"))
